import java.util.*;

public class Main {
    static int minSwapsCouples(int[] row) {
        int n = row.length;
        int[] arr = row.clone();
        int swaps = 0;

        for (int i = 0; i < n; i += 2) {
            int partner = arr[i] % 2 == 0 ? arr[i] + 1 : arr[i] - 1;
            if (arr[i + 1] != partner) {
                int j = i + 1;
                while (arr[j] != partner) j++;
                int tmp = arr[i + 1];
                arr[i + 1] = arr[j];
                arr[j] = tmp;
                swaps++;
            }
        }
        return swaps;
    }

    public static void main(String[] args) {
        System.out.println(minSwapsCouples(new int[]{0, 2, 1, 3}));
        System.out.println(minSwapsCouples(new int[]{3, 2, 0, 1}));
    }
}

